const el = (id) => document.getElementById(id);
const nfmt = (n, digits=1) => new Intl.NumberFormat('nb-NO',{minimumFractionDigits:digits,maximumFractionDigits:digits}).format(n);
const esc = (s) => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const parse = (o) => Number(o.verdi);
const serie = (navn) => OBSERVASJONER.filter(o=>o.serie===navn);
const figurvalg = {
 fond:{type:'line',tittel:'Oljefondets markedsverdi',enhet:'mrd. NOK',kilde:'K06',rows:()=>serie('fond_historikk'),note:'Observerte nominelle markedsverdier ved utgangen av kalenderåret. Endringer påvirkes også av kronekurs og fondstilførsler, ikke bare investeringsavkastning.'},
 skatt:{type:'bar',tittel:'Skatteinntekter av samlet BNP',enhet:'prosent',kilde:'K17',rows:()=>serie('skatt_2024'),note:'Målt mot samlet BNP i samtlige land. Den norske andelen skal ikke direkte sammenliknes med Fastlands-BNP som nevner.'},
 bolig:{type:'bar',tittel:'Registrert boligformue innen fylte 25 år',enhet:'prosent',kilde:'K08',rows:()=>serie('boligeierskap_ung').filter(o=>o.periode==='alder-25'),note:'SSBs analyse av personer født 1988–1993, gruppert etter foreldrenes formuesposisjon. Observasjonsforskjellen er ikke en kausal effektberegning.'},
 offentlig:{type:'bar',tittel:'Offentlig utgiftsandel av totalt BNP',enhet:'prosent',kilde:'K03',rows:()=>serie('offutgift_2024'),note:'Norge og OECD sammenliknes med samme nevner: samlet BNP i 2024. Ikke sammenlikn dette direkte med «over 60 %» målt mot Fastlands-BNP.'},
 fastland:{type:'bar',tittel:'Årsvekst i Fastlands-BNP',enhet:'prosent',kilde:'K01',rows:()=>serie('fastlandsvekst'),note:'Årlig volumendring i Fastlands-BNP, foreløpige nasjonalregnskapstall. Ingen ekstra år er konstruert.'},
 fruktbarhet:{type:'bar',tittel:'Samlet fruktbarhetstall',enhet:'barn per kvinne',kilde:'K11',rows:()=>serie('fruktbarhet'),note:'Utvalgte enkeltår (2015, 2024, 2025), ikke en komplett tidsserie. Det er ingen interpolasjon mellom årene.'}
};
let gjeldendeRader=[],gjeldendeKilde='K06';
function labelOf(o){ if(o.serie==='boligeierskap_ung')return o.gruppe;if(o.serie==='skatt_2024'||o.serie==='offutgift_2024')return o.gruppe;return o.periode; }
function tegneGraf(type, rows, enhet){
 const w=660,h=300,L=60,R=16,T=28,B=62;
 const ys=rows.map(parse); if(!ys.length)return '<p>Ingen observasjoner.</p>';
 const maxV=Math.max(...ys,1);const minV=Math.min(0,...ys);const maxY=Math.ceil(maxV*1.15*10)/10; const minY=Math.min(0,minV);
 const sx=(i)=>L+(rows.length===1?.5:i/(rows.length-1))*(w-L-R);
 const sy=(v)=>h-B-((v-minY)/(maxY-minY))*(h-T-B);
 let out=`<svg viewBox="0 0 ${w} ${h}" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${esc(enhet)} for ${rows.length} observerte datapunkter">`;
 for(let j=0;j<=4;j++){const v=minY+(maxY-minY)*j/4,y=sy(v);out+=`<line x1="${L}" x2="${w-R}" y1="${y}" y2="${y}" stroke="var(--line)" stroke-width="1"/><text x="${L-10}" y="${y+4}" text-anchor="end" font-size="11" fill="var(--muted)">${esc(nfmt(v, v<10?1:0))}</text>`;}
 if(type==='line'){
  const points=rows.map((o,i)=>`${sx(i)},${sy(parse(o))}`).join(' ');
  out+=`<polyline points="${points}" fill="none" stroke="var(--main)" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round"/>`;
  rows.forEach((o,i)=>{let x=sx(i),y=sy(parse(o));out+=`<circle cx="${x}" cy="${y}" r="5" fill="var(--card)" stroke="var(--main)" stroke-width="2.8"><title>${esc(labelOf(o))}: ${esc(nfmt(parse(o),0))} ${esc(enhet)}</title></circle>`;if(i===0||i===rows.length-1||i%2===0)out+=`<text x="${x}" y="${h-B+22}" text-anchor="middle" font-size="11" fill="var(--muted)">${esc(labelOf(o))}</text>`;});
 }else{
  const area=w-L-R;const col=area/rows.length;const barW=Math.max(12,Math.min(68,col*.61));
  rows.forEach((o,i)=>{const x=L+i*col+(col-barW)/2, y=sy(Math.max(0,parse(o))), base=sy(0),bh=Math.max(1,base-y), v=parse(o),lab=labelOf(o);out+=`<rect x="${x}" y="${y}" width="${barW}" height="${bh}" rx="4" fill="${i===0?'var(--main)':'#78a9a8'}"><title>${esc(lab)}: ${esc(nfmt(v, v<10?2:1))} ${esc(enhet)}</title></rect><text x="${x+barW/2}" y="${y-8}" font-weight="700" text-anchor="middle" font-size="12" fill="var(--ink)">${esc(nfmt(v,v<10?2:1))}</text>`;
   let parts=lab.length>20?lab.split(' '):[lab];let lines=[];if(parts.length===1)lines=[lab];else {const m=Math.ceil(parts.length/2); lines=[parts.slice(0,m).join(' '),parts.slice(m).join(' ')];}
   lines.forEach((s,k)=>out+=`<text x="${x+barW/2}" y="${h-B+20+k*15}" text-anchor="middle" font-size="${rows.length>4?10:11}" fill="var(--muted)">${esc(s)}</text>`);
  });
 }
 out+='</svg>';return out;
}
// Separat landpanel for tråd 02: korrekt nullakse også ved negative vekstrater.
function oppdaterLandpanel(){
 const period=el('eu-periode').value;
 const rows=EUROSTAT02.filter(r=>r.periode===period);
 if(!rows.length){el('eu-graf').textContent='Ingen datapunkter i valgt periode.';return;}
 const W=750,H=320,L=55,R=18,T=35,B=70;
 const values=rows.map(r=>Number(r.vekst_prosent));
 const lo=Math.min(0,...values)-0.45,hi=Math.max(0,...values)+0.6;
 const y=v=>H-B-(v-lo)/(hi-lo)*(H-T-B);
 const zero=y(0),space=(W-L-R)/rows.length,bw=Math.min(58,space*.62);
 let svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="Arbeidsproduktivitet i ${esc(period)}. Se også teksttabell">`;
 for(let k=0;k<=5;k++){
   const v=lo+(hi-lo)*k/5,yy=y(v);
   svg+=`<line x1="${L}" x2="${W-R}" y1="${yy}" y2="${yy}" stroke="var(--line)" stroke-width="1"/><text x="${L-10}" y="${yy+4}" text-anchor="end" font-size="12" fill="var(--muted)">${esc(nfmt(v,1))}</text>`;
 }
 svg+=`<line x1="${L}" x2="${W-R}" y1="${zero}" y2="${zero}" stroke="var(--ink2)" stroke-width="1.4"/>`;
 rows.forEach((r,i)=>{
   const v=values[i],cx=L+space*(i+.5),xx=cx-bw/2,yy=y(v),ry=Math.min(zero,yy),rh=Math.max(1,Math.abs(zero-yy));
   svg+=`<rect x="${xx}" y="${ry}" width="${bw}" height="${rh}" rx="3" fill="${r.land==='Norge'?'var(--main)':'#88adb0'}"><title>${esc(r.land)}: ${esc(nfmt(v,1))} %</title></rect>`;
   svg+=`<text x="${cx}" y="${v>=0?Math.max(12,yy-8):Math.min(H-B+16,yy+17)}" text-anchor="middle" font-size="12" font-weight="700" fill="var(--ink)">${esc(nfmt(v,1))}</text>`;
   svg+=`<text x="${cx}" y="${H-B+24}" text-anchor="middle" font-size="12" fill="var(--ink2)">${esc(r.land)}</text>`;
 });
 svg+='</svg>';
 el('eu-graf').innerHTML=svg;
 el('eu-tabell-periode').textContent=period+(period.length===4?' · enkeltår':' · årlig snitt');
 el('eu-tabell').innerHTML='<table><thead><tr><th scope="col">Land</th><th scope="col">Vekst</th></tr></thead><tbody>'+rows.map(r=>`<tr><td>${esc(r.land)}</td><td>${esc(nfmt(Number(r.vekst_prosent),1))} %</td></tr>`).join('')+'</tbody></table>';
}
el('eu-periode').addEventListener('change',oppdaterLandpanel);
function oppdaterBnpPanel(){
 const W=760,H=310,L=60,R=20,T=22,B=53;
 const all=[...BNP02.map(o=>Number(o.fastlands_bnp_vekst_prosent)),...BNP02.map(o=>Number(o.samlet_bnp_vekst_prosent))];
 const lo=Math.floor(Math.min(0,...all)-.5),hi=Math.ceil(Math.max(0,...all)+.5);
 const x=i=>L+(W-L-R)*i/(BNP02.length-1),y=v=>H-B-(v-lo)/(hi-lo)*(H-T-B);
 let svg=`<svg viewBox="0 0 ${W} ${H}" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="SSBs årlige realvekst i BNP og Fastlands-BNP">`;
 for(let v=lo;v<=hi;v+=2){const yy=y(v);svg+=`<line x1="${L}" x2="${W-R}" y1="${yy}" y2="${yy}" stroke="var(--line)"/><text x="${L-8}" y="${yy+4}" text-anchor="end" font-size="11" fill="var(--muted)">${esc(v)}</text>`;}
 for(let i=0;i<BNP02.length;i+=4){svg+=`<text x="${x(i)}" y="${H-B+22}" text-anchor="middle" font-size="11" fill="var(--muted)">${esc(BNP02[i].aar)}</text>`;}
 [['fastlands_bnp_vekst_prosent','var(--main)'],['samlet_bnp_vekst_prosent','#b47d45']].forEach(([key,color])=>{
    const points=BNP02.map((r,i)=>`${x(i).toFixed(2)},${y(Number(r[key])).toFixed(2)}`).join(' ');
    svg+=`<polyline points="${points}" fill="none" stroke="${color}" stroke-width="2.8" stroke-linecap="round" stroke-linejoin="round"/>`;
 });
 svg+='</svg>';el('bnp-graf').innerHTML=svg;
 el('bnp-tabell').innerHTML='<table><thead><tr><th>År</th><th>Fastland</th><th>Samlet</th></tr></thead><tbody>'+BNP02.map(r=>`<tr><td>${esc(r.aar)}</td><td>${esc(nfmt(Number(r.fastlands_bnp_vekst_prosent),1))} %</td><td>${esc(nfmt(Number(r.samlet_bnp_vekst_prosent),1))} %</td></tr>`).join('')+'</tbody></table>';
}
function oppdaterFigur(){
 const valgt=figurvalg[el('figur-valg').value];const rows=valgt.rows();gjeldendeRader=rows;gjeldendeKilde=valgt.kilde;
 el('figur-graf').innerHTML=tegneGraf(valgt.type,rows,valgt.enhet);
 el('figur-graf').setAttribute('aria-label',valgt.tittel+' – se tilsvarende data i tabellen');
 el('figur-enhet').textContent=valgt.tittel+' · '+valgt.enhet;
 el('figur-kilde').textContent='Kilde ['+valgt.kilde+']';el('figur-kilde').href='#'+valgt.kilde.toLowerCase();
 el('figur-merknad').textContent=valgt.note;
 const headers='<thead><tr><th scope="col">År / gruppe</th><th scope="col">Verdi</th></tr></thead>';
 el('figur-tabell').innerHTML='<table>'+headers+'<tbody>'+rows.map(o=>'<tr><td>'+esc(labelOf(o))+'</td><td>'+esc(nfmt(parse(o),parse(o)<10?2:1))+'</td></tr>').join('')+'</tbody></table>';
}
function lagCSV(rows){
 const header='Indikator;Periode;Gruppe;Verdi;Enhet;Kilde';
 function q(s){return '"'+String(s).replace(/"/g,'""')+'"'}
 return '\uFEFF'+[header,...rows.map(o=>[o.indikator,o.periode,o.gruppe,o.verdi,o.enhet,o.kilde_id].map(q).join(';'))].join('\r\n')+'\r\n';
}
function lastNedTekst(txt,filnavn,format='text/csv;charset=utf-8'){
 const a=document.createElement('a');const url=URL.createObjectURL(new Blob([txt],{type:format}));a.href=url;a.download=filnavn;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
el('figur-valg').addEventListener('change',oppdaterFigur);el('eksporter-figur').addEventListener('click',()=>lastNedTekst(lagCSV(gjeldendeRader),'norsk-okonomi-'+el('figur-valg').value+'-data.csv'));el('eksporter-alt').addEventListener('click',()=>lastNedTekst(lagCSV(OBSERVASJONER),'norsk-okonomi-alle-observasjoner.csv'));

function tegnLinjeSvg(values, maxX=30){
 const W=590,H=175,L=45,R=15,T=14,B=24;const lo=Math.min(0,...values),hi=Math.max(...values,1)*1.08;
 const x=i=>L+(W-L-R)*i/maxX, y=v=>H-B-(H-T-B)*(v-lo)/(hi-lo);
 const line=values.map((v,i)=>`${x(i)},${y(v)}`).join(' ');
 let s=`<line x1="${L}" y1="${H-B}" x2="${W-R}" y2="${H-B}" stroke="var(--line)"/><polyline points="${line}" fill="none" stroke="var(--main)" stroke-width="3" stroke-linejoin="round"/>`;
 [0,10,20,30].forEach(i=>s+=`<text x="${x(i)}" y="${H-5}" font-size="11" text-anchor="middle" fill="var(--muted)">${2025+i}</text>`);
 [0,values.length-1].forEach(i=>s+=`<circle cx="${x(i)}" cy="${y(values[i])}" r="4.5" fill="var(--card)" stroke="var(--main)" stroke-width="2.5"/>`);
 s+=`<text x="${L}" y="${T+9}" fill="var(--muted)" font-size="10">Fondsverdi, mrd. kr</text>`;return s;
}
function oppdaterFond(){
 const r=parseFloat(el('avkastning').value)/100,g=parseFloat(el('uttaksvekst').value)/100;
 el('avkastning-v').textContent=nfmt(r*100,1)+' %';el('uttaksvekst-v').textContent=nfmt(g*100,1)+' %';
 let f=21268,u=579;const values=[f];let totalU=0;
 for(let i=0;i<30;i++){f=f*(1+r)-u;totalU+=u;u=u*(1+g);values.push(f);}
 el('fond-resultat').textContent=nfmt(f,0);el('fonds-kurve').innerHTML=tegnLinjeSvg(values);el('fonds-beregning').textContent='Samlet uttak over 30 modellår: '+nfmt(totalU,0)+' mrd. kr. Fondsverdi ved start: 21 268 mrd. kr. Resultatet er betinget av de valgte satsene.';
 el('fonds-kurve').setAttribute('aria-label','Beregnet fondsverdi fra 2025 til 2055. Start '+nfmt(values[0],0)+' mrd. kroner, slutt '+nfmt(f,0)+' mrd. kroner.');
}
['avkastning','uttaksvekst'].forEach(id=>el(id).addEventListener('input',oppdaterFond));
function oppdaterBolig(){
 const fall=Number(el('boligfall').value),bolig=9159,netto=11958,tap=bolig*fall/100,result=netto-tap;
 el('boligfall-v').textContent=fall+' %';el('bolig-resultat').textContent=nfmt(result,1);
 const pct=Math.max(0,result/netto*100);
 el('bolig-barer').innerHTML=`<div style="font-size:12px;color:var(--muted);margin-top:14px">Beregnet nettoformue før fall</div><div style="height:21px;background:var(--soft2);border-radius:4px;margin:6px 0 19px;width:100%"><div style="height:100%;width:100%;background:#91a9b5;border-radius:4px"></div></div><div style="font-size:12px;color:var(--muted)">Beregnet nettoformue etter fall</div><div style="height:21px;background:var(--soft2);border-radius:4px;margin:6px 0 5px;width:100%"><div style="height:100%;width:${pct}%;background:var(--main);border-radius:4px;transition:width .15s"></div></div>`;
 el('bolig-beregning').textContent='Reduksjon i beregnet boligverdi: '+nfmt(tap,1)+' mrd. kr. Dette er '+nfmt(tap/netto*100,1)+' % av avgrenset nettoformue i 2024 (ikke SSBs fullstendige husholdningsformue).';
 el('bolig-barer').setAttribute('aria-label','Før: '+nfmt(netto,1)+' mrd.; etter: '+nfmt(result,1)+' mrd. kroner.');
}
