// Utvidet tråd 02 — diagram og samtidig tabell fra maskinlesbare kilder.
function oppdaterUtvidetLandpanel(){
 const metric=el('land-metrikk').value;
 let rows=TILLEGG02.filter(r=>r.indikator===metric);
 if(!metric.includes('vareeksport') && metric!=='Fastlandseksport av varer')rows=rows.filter(r=>r.periode==='2025');
 rows=rows.slice().sort((a,b)=>{if(metric.includes('vareeksport')||metric.includes('naturgass')) return Number(a.periode)-Number(b.periode);return Number(b.verdi)-Number(a.verdi);});
 const max=Math.max(1,...rows.map(r=>Number(r.verdi)));
 const k=rows[0]?.kilde_id||'K42'; const unit=rows[0]?.enhet||'';
 el('land-ekstra-graf').innerHTML=rows.map(r=>{
  const label=(r.land==='Norge' && (metric.includes('eksport')||metric.includes('naturgass')))?r.periode:r.land;
  const pct=100*Number(r.verdi)/max;
  return `<div style="display:grid;grid-template-columns:minmax(72px,120px) minmax(20px,1fr) 78px;gap:9px;align-items:center;margin:8px 0;font-size:12px"><span>${esc(label)}</span><div style="height:13px;border-radius:3px;background:var(--soft2)"><div style="height:100%;width:${pct.toFixed(2)}%;background:${r.land==='Norge'?'var(--main)':'#a8b8c1'};border-radius:3px"></div></div><b style="text-align:right;font-variant-numeric:tabular-nums">${esc(nfmt(Number(r.verdi),unit.includes('indeks')||unit.includes('EU27')?1:2))}</b></div>`;
 }).join('');
 el('land-ekstra-tabell').innerHTML=`<table><thead><tr><th>Land / år</th><th>Verdi</th><th>Enhet</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.land==='Norge'&&rows.every(x=>x.land==='Norge')?r.periode:r.land)}</td><td>${esc(nfmt(Number(r.verdi),2))}</td><td>${esc(unit)}</td></tr>`).join('')}</tbody></table>`;
 el('land-ekstra-kilde').href='#'+k.toLowerCase();el('land-ekstra-kilde').textContent='['+k+']';el('land-ekstra-enhet').textContent=unit;
 el('land-ekstra-forklaring').textContent=rows[0]?.merknad||'Ingen merknad';
 el('land-ekstra-graf').setAttribute('aria-label',metric+', '+rows.length+' sammenlignbare observasjoner');
}
