// Tråd 03: interaktive, direkte lesbare datasett uten eksterne biblioteker.
function figur03Klar(){
 const mode=el('bolig-datavalg').value;let rows=[],unit='',desc='',title='',series='';
 if(mode==='pris'){
   rows=PRIS03.map(r=>({label:r.aar,valu:Number(r.prisindeks)}));unit='indeks (2015=100)';title='Bruktboligprisindeks, årlig 1993–2025';desc='Nominell indeks fra SSB; et indeksnivå på 152,5 betyr ikke 152,5 prosent prisvekst siden 1993.';series='boligpris_aar_03';
 } else if(mode==='bygg'){
   rows=BYGG03.map(r=>({label:r.aar,valu:Number(r.igangsettingstillatelser),valu2:Number(r.fullforte)}));unit='antall boliger';title='Igangsettingstillatelser og fullførte boliger';desc='Ferdigstillelsene er ikke de samme boligene som fikk tillatelse samme kalenderår.';series='boligbygging_aar_03';
 } else {
   rows=REGION03.map(r=>({label:r.region,valu:Number(r.aar_aar_endring_prosent)}));unit='prosent endring, år/år';title='Nominelle regionale prisendringer';desc='Endring andre kvartal 2025 til andre kvartal 2026. Ikke sesongjustert kvartalsrate.';series='boligpriser_regioner_03';
 }
 const W=780, H=mode==='region'?410:310,L=55,R=22,T=35,B=mode==='region'?35:52;
 const max=Math.max(1,...rows.map(r=>r.valu),...rows.map(r=>r.valu2??0))*1.12;
 const sy=v=>H-B-(v/max)*(H-T-B);
 let out=`<svg viewBox="0 0 ${W} ${H}" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${esc(title)}"><title>${esc(title)}</title>`;
 for(let j=0;j<=4;j++){let v=max*j/4,y=sy(v);out+=`<line x1="${L}" x2="${W-R}" y1="${y}" y2="${y}" stroke="var(--line)"/><text x="${L-10}" y="${y+4}" text-anchor="end" font-size="11" fill="var(--muted)">${esc(nfmt(v,mode==='region'?1:0))}</text>`;}
 if(mode==='region'){
    rows.forEach((r,i)=>{let y=T+i*(H-T-B)/rows.length+3, bw=(W-L-R)*r.valu/max;out+=`<text x="${L+4}" y="${y+12}" fill="var(--ink)" font-size="12">${esc(r.label)}</text><rect x="${L+280}" y="${y}" width="${Math.max(1,bw*.57)}" height="${Math.max(8,(H-T-B)/rows.length-8)}" rx="2" fill="var(--main)"/><text x="${L+290+Math.max(1,bw*.57)}" y="${y+12}" fill="var(--ink)" font-size="12">${esc(nfmt(r.valu,1))} %</text>`;});
 }else{
   const x=i=>L+i/(rows.length-1)*(W-L-R);
   out+=`<polyline points="${rows.map((r,i)=>x(i)+','+sy(r.valu)).join(' ')}" stroke="var(--main)" stroke-width="3" fill="none" stroke-linejoin="round"/>`;
   if(mode==='bygg')out+=`<polyline points="${rows.map((r,i)=>x(i)+','+sy(r.valu2)).join(' ')}" stroke="#b78049" stroke-width="3" fill="none" stroke-linejoin="round"/>`;
   rows.forEach((r,i)=>{if(i%4===0||i===rows.length-1)out+=`<text x="${x(i)}" y="${H-21}" font-size="11" text-anchor="middle" fill="var(--muted)">${r.label}</text>`;out+=`<circle cx="${x(i)}" cy="${sy(r.valu)}" r="3" fill="var(--main)"><title>${r.label}: ${r.valu}</title></circle>`;});
   if(mode==='bygg')out+=`<text x="${L+3}" y="${H-3}" fill="var(--main)" font-size="12">— Tillatelser</text><text x="${L+140}" y="${H-3}" fill="#b78049" font-size="12">— Fullførte</text>`;
 }
 out+='</svg>';
 el('bolig03-graf').innerHTML=out;el('bolig03-merknad').textContent=desc;el('bolig03-tittel').textContent=title;
 const heads=mode==='bygg'?['År','Tillatelser','Fullførte']:mode==='region'?['Region','Endring']:['År','Indeks'];
 el('bolig03-tabell').innerHTML=`<table><thead><tr>${heads.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.label)}</td><td>${esc(nfmt(r.valu,mode==='bygg'?0:1))}</td>${mode==='bygg'?`<td>${esc(nfmt(r.valu2,0))}</td>`:''}</tr>`).join('')}</tbody></table>`;
 el('bolig03-graf').setAttribute('aria-label',title+', '+rows.length+' datarader');
 el('bolig03-eksporter').onclick=()=>lastNedTekst(lagCSV(mode==='pris'?PRIS03:mode==='bygg'?BYGG03:REGION03),'norsk-okonomi-'+series+'.csv');
}
el('bolig-datavalg').addEventListener('change',figur03Klar);
function tegnGen03(){
 let ages=[...new Set(GEN03.map(x=>x.alder))].sort((a,b)=>a-b);const W=660,H=260,L=50,R=15,T=15,B=44,max=100;
 const sy=v=>H-B-(v/max)*(H-T-B), gap=(W-L-R)/ages.length;
 let out=`<svg viewBox="0 0 ${W} ${H}" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Boligeierskap etter alder og foreldres formue">`;
 for(let j=0;j<=4;j++){const y=sy(j*25);out+=`<line x1="${L}" y1="${y}" x2="${W-R}" y2="${y}" stroke="var(--line)"/><text x="${L-7}" y="${y+4}" font-size="11" text-anchor="end" fill="var(--muted)">${j*25}</text>`;}
 ages.forEach((a,i)=>{let low=GEN03.find(x=>x.alder===a&&x.gruppe.includes('nederste')),high=GEN03.find(x=>x.alder===a&&x.gruppe.includes('øverste'));let cen=L+(i+.5)*gap;
  [[low,-24,'var(--main)'],[high,6,'#b78049']].forEach(([r,offset,col])=>{const hh=H-B-sy(r.andel_prosent);out+=`<rect x="${cen+offset}" y="${sy(r.andel_prosent)}" width="22" height="${hh}" rx="3" fill="${col}"><title>Ved ${a} år, ${esc(r.gruppe)}: ${r.andel_prosent}%</title></rect>`;});
  out+=`<text x="${cen}" y="${H-17}" text-anchor="middle" fill="var(--ink2)" font-size="12">${a} år</text>`;});
 out+='</svg>';el('generasjon03-graf').innerHTML=out;
 el('generasjon03-tabell').innerHTML='<p class="chart-meta">Har noen gang hatt boligformue innen alder, prosent</p><table><thead><tr><th>Alder</th><th>Nederste 25 %</th><th>Øverste 2 %</th></tr></thead><tbody>'+ages.map(a=>'<tr><td>'+a+'</td><td>'+nfmt(GEN03.find(x=>x.alder===a&&x.gruppe.includes('nederste')).andel_prosent,1)+' %</td><td>'+nfmt(GEN03.find(x=>x.alder===a&&x.gruppe.includes('øverste')).andel_prosent,1)+' %</td></tr>').join('')+'</tbody></table>';
}
function oppdaterLaan03(){
 const price=Number(el('boligkjop03').value),r=Number(el('rente03').value)/1200,pct=Number(el('egenkap03').value)/100;
 const debt=price*(1-pct),mo=r?debt*r/(1-Math.pow(1+r,-360)):debt/360;
 el('boligkjop03-v').textContent=nfmt(price/1e6,1)+' mill.';el('rente03-v').textContent=nfmt(r*1200,1)+' %';el('egenkap03-v').textContent=nfmt(pct*100,0)+' %';el('termin03').textContent=nfmt(mo,0)+' kr';
 el('inntekt03').innerHTML='<strong>Egenkapital:</strong> '+nfmt(price*pct,0)+' kr · <strong>Lån:</strong> '+nfmt(debt,0)+' kr · <strong>Minste brutto årsinntekt etter 5×-grensen:</strong> '+nfmt(debt/5,0)+' kr (uten annen gjeld). <strong>Rentestresstest:</strong> minst '+nfmt(Math.max(7,r*1200+3),1)+' % årlig rente skal kunne betjenes.';
}
['boligkjop03','rente03','egenkap03'].forEach(id=>el(id).addEventListener('input',oppdaterLaan03));
figur03Klar();tegnGen03();oppdaterLaan03();


// Forskningstråd 04: kun publiserte SSB-data, med separat merking av populasjon og mål.
function renderGenerasjon04(){
 const mode=el('gen04-visning').value;
 let years=[], groupA=[],groupB=[],legendA='',legendB='',sources='',note='', csvData=[],max=100;
 if(mode==='tverrsnitt'){
   years=[...new Set(EIER04.filter(x=>x.gruppe==='Alle').map(x=>x.alder))].sort((a,b)=>a-b);
   groupA=years.map(age=>Number(EIER04.find(x=>x.gruppe==='Alle'&&x.alder===age&&x.aar===2014).andel_prosent));
   groupB=years.map(age=>Number(EIER04.find(x=>x.gruppe==='Alle'&&x.alder===age&&x.aar===2023).andel_prosent));
   legendA='2014';legendB='2023';max=80;csvData=EIER04;
   sources='K08';note='Tverrsnitt: andel med boligformue ved utgangen av 2014 og 2023; ikke de samme individene. SSB, [K08].';
 }else if(mode==='foreldre'){
   years=[...new Set(FORELDRE04.map(x=>x.alder))].sort((a,b)=>a-b);
   groupA=years.map(a=>Number(FORELDRE04.find(x=>x.alder===a&&x.foreldreformue_gruppe.includes('nederste')).andel_prosent));
   groupB=years.map(a=>Number(FORELDRE04.find(x=>x.alder===a&&x.foreldreformue_gruppe.includes('øverste')).andel_prosent));
   legendA='Nederste 25 %';legendB='Øverste 2 %';max=100;csvData=FORELDRE04;
   sources='K08';note='Fødte 1988–1993 og bosatte både 2005 og 2023. Har noen gang hatt boligformue innen alder; ved 31–33 år er bare fødte som oppnådde denne alderen inkludert. Observerte gap er ikke kausale effekter.';
 }else{
   years=[...new Set(BYRDE04.map(x=>x.aar))].sort((a,b)=>a-b);
   groupA=years.map(y=>Number(BYRDE04.find(x=>x.aar===y&&x.aldersgruppe==='25–44 år').andel_prosent));
   groupB=years.map(y=>Number(BYRDE04.find(x=>x.aar===y&&x.aldersgruppe==='67 år og eldre').andel_prosent));
   legendA='25–44 år';legendB='67 år og eldre';max=16;csvData=BYRDE04;
   sources='K69';note='Andel i EU-SILC som sier at boutgiftene er svært tyngende. Datapunkter mangler for 2021, 2022 og 2024; ingen interpolasjon. Aldersgrupper, ikke fødselskull.';
 }
 const W=780,H=310,L=48,R=12,T=48,B=54,spacing=(W-L-R)/years.length;
 const sy=v=>H-B-(v/max)*(H-T-B);
 let svg=`<svg viewBox="0 0 ${W} ${H}" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="To seriegrupper for ${esc(note)}">`;
 for(let k=0;k<=4;k++){let v=max*k/4,y=sy(v);svg+=`<line x1="${L}" y1="${y}" x2="${W-R}" y2="${y}" stroke="var(--line)"/><text x="${L-8}" y="${y+4}" text-anchor="end" font-size="12" fill="var(--muted)">${nfmt(v,0)} %</text>`;}
 svg+=`<rect x="${L}" y="12" width="12" height="12" fill="var(--main)"/><text x="${L+18}" y="23" fill="var(--ink2)" font-size="13">${esc(legendA)}</text><rect x="${L+198}" y="12" width="12" height="12" fill="#b78049"/><text x="${L+216}" y="23" fill="var(--ink2)" font-size="13">${esc(legendB)}</text>`;
 const bar=Math.min(17,spacing*.34);
 years.forEach((yr,i)=>{
   const x=L+(i+.5)*spacing;
   [[groupA[i],-bar-1,'var(--main)',legendA],[groupB[i],1,'#b78049',legendB]].forEach(([v,offset,color,label])=>{
     svg+=`<rect x="${x+offset}" y="${sy(v)}" width="${bar}" height="${Math.max(0,H-B-sy(v))}" rx="2" fill="${color}"><title>${esc(String(yr))}: ${nfmt(v,1)} % (${esc(label)})</title></rect>`;
   });
   svg+=`<text x="${x}" y="${H-23}" text-anchor="middle" font-size="${years.length>11?11:13}" fill="var(--ink2)">${esc(String(yr))}</text>`;
 });
 svg+='</svg>';
 el('gen04-graf').innerHTML=svg;
 el('gen04-graf').setAttribute('aria-label',note);
 el('gen04-tabell').innerHTML=`<table><thead><tr><th>${mode==='belastning'?'År':'Alder'}</th><th>${esc(legendA)}</th><th>${esc(legendB)}</th></tr></thead><tbody>${years.map((yr,i)=>`<tr><td>${esc(String(yr))}</td><td>${nfmt(groupA[i],1)} %</td><td>${nfmt(groupB[i],1)} %</td></tr>`).join('')}</tbody></table>`;
 el('gen04-tekst').textContent=note+' Kilde: '+sources+'.';
 el('gen04-csv').onclick=()=>lastNedTekst(lagCSV(csvData),'norsk-okonomi-generasjoner-'+mode+'-04.csv');
}
function calcGenerasjon04(){
 const P=Number(el('gen04-pris').value)*1000000;
 const Y=Number(el('gen04-inntekt').value)*1000;
 const S=Number(el('gen04-egne').value)*1000;
 const T=Number(el('gen04-stotte').value)*1000;
 const D=Number(el('gen04-gjeld').value)*1000;
 const Lmax=Math.max(0,Math.min(.9*P,5*Y-D));
 const Ereq=Math.max(0,P-Lmax);
 const gap=Math.max(0,Ereq-S-T);
 const entries={pris:nfmt(P/1e6,1)+' mill. kr',inntekt:nfmt(Y,0)+' kr',egne:nfmt(S,0)+' kr',stotte:nfmt(T,0)+' kr',gjeld:nfmt(D,0)+' kr'};
 Object.keys(entries).forEach(k=>el('gen04-'+k+'-v').textContent=entries[k]);
 el('gen04-resultat').innerHTML=`<strong>Teoretisk lånetak:</strong> ${nfmt(Lmax,0)} kr<br><strong>Nødvendige egne midler og overføringer:</strong> ${nfmt(Ereq,0)} kr<br><strong>Resterende finansieringsgap:</strong> <strong>${nfmt(gap,0)} kr</strong><br><span class="chart-note">${gap>0?'Rammen oppfylles ikke med disse forutsetningene.':'Kun beløpsgrensene er oppfylt. Betjeningsevne og øvrige bankvilkår er ikke testet.'}</span>`;
}
function rendKohort04(){
 const y=Number(el('gen04-kohort').value);
 el('gen04-kohorttabell').innerHTML='<table><thead><tr><th>Alder</th><th>Kalenderår</th><th>Observasjonsgrense</th></tr></thead><tbody>'+
 [25,30,35,40].map(a=>{const year=y+a;return `<tr><td>${a} år</td><td>${year}</td><td>${year<=2025?'Historisk år; paneldata gjenstår':'Fremtidig alder — ingen observasjon'}</td></tr>`;}).join('')+'</tbody></table>';
}
el('gen04-visning').addEventListener('change',renderGenerasjon04);
['pris','inntekt','egne','stotte','gjeld'].forEach(s=>el('gen04-'+s).addEventListener('input',calcGenerasjon04));
el('gen04-kohort').addEventListener('change',rendKohort04);
renderGenerasjon04();calcGenerasjon04();rendKohort04();


// Tråd 05: verdier fra eksplisitte datasett. De separate kategoriene sammenslås aldri.
function tegnStartups05(){
 const mode=el('startup05-valg').value;
 let title='',note='',unit='',key='K77',data=[];
 if(mode==='registrering'){
  title='Nyregistrerte foretak per kvartal';unit='foretak';key='K77';
  data=STARTUP_FORETAK05.map(r=>({label:r.periode,value:Number(r.totalt)}));
  note='SSB tabell 08076. Antall nye registreringer per kvartal, ikke antall overlevende arbeidsgiverforetak. Metodeendring fra 2026 må hensyntas.';
 } else if(mode==='venture'){
  title='Investert tidligfasekapital i 2025';unit='millioner euro';key='K82';
  data=STARTUP_VC05.map(r=>({label:r.land,value:Number(r.mill_eur)}));
  note='NVCA/Menon: avrundede investeringer i selskaper etter porteføljeselskapets hjemland, slik bransjerapporten oppgir dem. Ikke BNP-justert; fondsdatadekning og investordefinisjon setter grenser for sammenligningen.';
 } else if(mode==='vekst'){
  title='Lovende startups etter 3, 6 og 9 år';unit='prosent av utvalgt startuppopulasjon';key='K79';
  data=STARTUP_VEKST05.map(r=>({label:r.aar_etter+' år',value:Number(r.fortsatt_vekst_prosent),other:Number(r.blitt_scaleup_prosent)}));
  note='SSB forløpsanalyse: primærserie er fortsatt vekst; andelen scaleups er inkludert i og IKKE lagt til primærserien. Omtrentlig for selekterte lovende oppstartsforetak — ikke overlevelse blant alle nyregistrerte.';
 } else if(mode==='alder'){
  title='Aldersfordeling blant personlige etablerere, 2024';unit='prosent av personlige etablerere';key='K81';
  data=STARTUP_ALDER05.map(r=>({label:r.gruppe,value:Number(r.andel_prosent)}));
  note='SSB: 64 622 personlige etablerere totalt. Foreløpige anslag og avrundet aldersfordeling; dette er ikke foretak eller aldersspesifikk etableringsrate.';
 } else if(mode==='ledig'){
  title='AKU-arbeidsledighet 15–24 år';unit='prosent av arbeidsstyrken';key='K87';
  data=STARTUP_LEDIG05.map(r=>({label:String(r.aar),value:Number(r.ledighet_15_24_prosent)}));
  note='SSBs AKU-ledighet for unge. Nevner er arbeidsstyrken 15–24 år; skal ikke settes lik eller summeres med register-NEET for 15–29-åringer.';
 } else {
  title='Nyutdannede med høyere utdanning i akademiske yrker m.m.';unit='prosent av høyere utdannede nyutdannede';key='K88';
  data=STARTUP_NYUTD05.map(r=>({label:String(r.aar),value:Number(r.andel_akademiske_yrker_prosent)}));
  note='SSB/AKU figur 4. Andelen i yrkesgrupper med akademisk innhold, ikke samlet sysselsetting. Tidsserie her viser bare 2024/2025 med eksplisitt kildegrunnlag.';
 }
 el('startup05-tittel').textContent=title;
 el('startup05-forklaring').textContent=note+' Enhet: '+unit+'.';
 el('startup05-kilde').textContent='Kilde ['+key+']';el('startup05-kilde').href='#'+key.toLowerCase();
 const max=Math.max(1,...data.map(x=>x.value))*1.13,W=750,H=328,L=65,R=20,T=40,B=65,usable=W-L-R,cw=usable/data.length,bar=Math.min(66,cw*.53);
 const Y=v=>H-B-(v/max)*(H-T-B);
 let svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(title)}. Kilde ${key}.">`;
 for(let tick=0;tick<=4;tick++){const v=max*tick/4,yy=Y(v);svg+=`<line x1="${L}" x2="${W-R}" y1="${yy}" y2="${yy}" stroke="var(--line)"/><text x="${L-8}" y="${yy+4}" text-anchor="end" font-size="11" fill="var(--muted)">${esc(nfmt(v,v>=100?0:1))}</text>`;}
 data.forEach((r,i)=>{
  const cx=L+cw*(i+.5),x=cx-bar/2,y=Y(r.value),h=Math.max(2,H-B-y);
  svg+=`<rect x="${x}" y="${y}" width="${bar}" height="${h}" fill="var(--main)" rx="2"><title>${esc(r.label)}: ${esc(nfmt(r.value,r.value>=100?0:1))} ${esc(unit)}</title></rect>`;
  if(r.other!==undefined){const w=Math.max(6,bar*.39),h2=Math.max(2,H-B-Y(r.other));svg+=`<rect x="${cx+bar*.28}" y="${Y(r.other)}" width="${w}" height="${h2}" fill="#bd8648" rx="2"><title>${esc(r.label)}: ${esc(nfmt(r.other,1))} % ble scaleups</title></rect>`;}
  svg+=`<text x="${cx}" y="${Math.max(17,y-8)}" text-anchor="middle" fill="var(--ink)" font-size="12" font-weight="650">${esc(nfmt(r.value,r.value>=100?0:1))}</text>`;
  svg+=`<text x="${cx}" y="${H-B+21}" text-anchor="middle" fill="var(--muted)" font-size="${r.label.length>11?10:12}">${esc(r.label)}</text>`;
 });
 if(mode==='vekst')svg+=`<rect x="${L+8}" y="5" width="11" height="11" fill="var(--main)"/><text x="${L+26}" y="15" font-size="12" fill="var(--ink)">Fortsatt vekst</text><rect x="${L+150}" y="5" width="11" height="11" fill="#bd8648"/><text x="${L+168}" y="15" font-size="12" fill="var(--ink)">Blitt scaleup (inngår i vekst)</text>`;
 svg+='</svg>';el('startup05-graf').innerHTML=svg;
 el('startup05-tabell').innerHTML=`<table><thead><tr><th>Kategori</th><th>${esc(unit)}</th>${mode==='vekst'?'<th>Scaleup (inngår)</th>':''}</tr></thead><tbody>${data.map(r=>`<tr><td>${esc(r.label)}</td><td>${esc(nfmt(r.value,r.value>=100?0:1))}</td>${mode==='vekst'?`<td>${esc(nfmt(r.other,1))} %</td>`:''}</tr>`).join('')}</tbody></table>`;
 const csvQ=v=>'"'+String(v).replace(/"/g,'""')+'"';
 const header=['Figur','Kategori','Verdi','Enhet','Kilde',...(mode==='vekst'?['Andel scaleups (inngår i vekst)']:[])];
 const output=[header,...data.map(r=>[title,r.label,r.value,unit,key,...(mode==='vekst'?[r.other]:[])])];
 const csv='\uFEFF'+output.map(row=>row.map(csvQ).join(';')).join('\r\n')+'\r\n';
 el('startup05-csv').onclick=()=>lastNedTekst(csv,'norsk-okonomi-del05-'+mode+'.csv');
}
el('startup05-valg').addEventListener('change',tegnStartups05);
tegnStartups05();

// Tråd 06. Kategorier fra ulike registre og ulike rettslige statuser kan ikke summeres.
function tegnSkatt06(){
 const mode=el('tax06-valg').value;
 let title='',note='',unit='',key='K97',data=[],headers=[],rows=[];
 if(mode==='flytting'){
  title='Flyttinger i utvalg av 3 565 formuende, 2021–2025';unit='personer';key='K97';
  data=TAX_FLYT06.map(r=>({label:String(r.aar),value:Number(r.utflyttere_antal),other:Number(r.innflyttere_antal)}));
  headers=['År','Utflyttere','Innflyttere'];rows=TAX_FLYT06.map(r=>[r.aar,r.utflyttere_antal,r.innflyttere_antal]);
  note='Utvalg fra NOU 2026: 9, tabell 3.2–3.3. 141 registrerte utflyttere og 46 innflyttere. IKKE samlet migrasjon blant rike, IKKE kausalt antall skatteutflyttere. Andre populasjoner og datoer kan gi andre tall.';
 }else if(mode==='latent'){
  title='Latente gevinster, utflyttingsskattesaker';unit='mrd. kr, urealisert';key='K97';
  data=TAX_EXIT06.map(r=>({label:String(r.aar),value:Number(r.latent_gevinst_mill_kr)/1000}));
  headers=['År','Saker','Fastsatt latent gevinst (mill. kr)'];rows=TAX_EXIT06.map(r=>[r.aar,r.antall_saker,r.latent_gevinst_mill_kr]);
  note='NOU tabell 3.4. Beløp gjelder fastsatte latente gevinster; ingen av søylene viser faktiske kapitaltransaksjoner ut av Norge, skattebetaling eller bedrifter som flyttet.';
 }else if(mode==='satser'){
  title='Verdsetting og sats på formell beregningsverdi, 2026';unit='% før bunnfradrag';key='K93';
  data=TAX_SAT06.map(r=>({label:r.eiendel,value:Number(r.effektiv_sats_trinn1_prosent),other:Number(r.effektiv_sats_trinn2_prosent)}));
  headers=['Formuesobjekt','Formell rabatt (%)','Nedre marginaltrinn (%)','Øvre marginaltrinn (%)'];rows=TAX_SAT06.map(r=>[r.eiendel,r.formell_rabatt_prosent,r.effektiv_sats_trinn1_prosent,r.effektiv_sats_trinn2_prosent]);
  note='Vedtak 2026. Regnestykket multipliserer bare formell verdsettingsandel og marginalsats. Faktisk skatt påvirkes av bunnfradrag, gjeld, særregler og skattemessig verdsettelse; dette er ikke en beregning av effektiv skatt for alle skattytere.';
 }else{
  title='Statiske provenyendringer i Skattekommisjonens reformscenarier';unit='mrd. kr lavere årlig proveny';key='K98';
  data=TAX_NOU06.map(r=>({label:String(r.sats_prosent).replace('.',',')+' %',value:Math.abs(Number(r.anslatt_statisk_provenyendring_mrd_kr))}));
  headers=['Foreslått enhetssats (%)','Anslått statisk provenyendring (mrd. kr)'];rows=TAX_NOU06.map(r=>[r.sats_prosent,r.anslatt_statisk_provenyendring_mrd_kr]);
  note='NOU 2026: 9, tabell 6.2. Foreslåtte satser for utvidet skattegrunnlag, bunnfradrag 2 mill. kr og ekstra boligfradrag 7 mill. kr. Tallene er statiske budsjettscenarier, ikke vedtatt rett eller estimert BNP-effekt.';
 }
 el('tax06-tittel').textContent=title;
 el('tax06-merknad').textContent=note+' Enhet: '+unit+'.';
 el('tax06-kilde').textContent='Se kilde ['+key+']';el('tax06-kilde').href='#'+key.toLowerCase();
 const W=760,H=323,L=64,R=22,T=42,B=80,M=Math.max(1,...data.map(r=>Math.max(r.value,r.other??0)))*1.14;
 const cw=(W-L-R)/data.length,bar=Math.min(58,cw*(mode==='satser'||mode==='flytting'?.25:.5));
 const sy=v=>H-B-(v/M)*(H-T-B);
 let svg=`<svg viewBox="0 0 ${W} ${H}" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${esc(title)}. Tabell med tall følger.">`;
 for(let k=0;k<=4;k++){const v=M*k/4,y=sy(v);svg+=`<line x1="${L}" x2="${W-R}" y1="${y}" y2="${y}" stroke="var(--line)"/><text x="${L-7}" y="${y+4}" text-anchor="end" font-size="11" fill="var(--muted)">${esc(nfmt(v,v>=100?0:1))}</text>`;}
 if(data.some(r=>r.other!==undefined))svg+=`<rect x="${L+4}" y="6" width="11" height="11" fill="var(--main)"/><text x="${L+22}" y="16" fill="var(--ink2)" font-size="12">${mode==='flytting'?'Utflytting':'Nedre trinn'}</text><rect x="${L+166}" y="6" width="11" height="11" fill="#bc854b"/><text x="${L+185}" y="16" fill="var(--ink2)" font-size="12">${mode==='flytting'?'Innflytting':'Øvre trinn'}</text>`;
 data.forEach((r,i)=>{
   const cx=L+cw*(i+.5),w=r.other===undefined?bar*1.6:bar;
   const col=r.other===undefined?[{x:cx-w/2,v:r.value,c:'var(--main)'}]:[{x:cx-w-1,v:r.value,c:'var(--main)'},{x:cx+1,v:r.other,c:'#bc854b'}];
   col.forEach(a=>{const y=sy(a.v),height=Math.max(2,H-B-y);svg+=`<rect x="${a.x}" y="${y}" width="${w}" height="${height}" rx="2" fill="${a.c}"><title>${esc(r.label)}: ${nfmt(a.v,a.v>=50?0:2)} ${esc(unit)}</title></rect>`;});
   svg+=`<text x="${cx}" y="${H-B+24}" text-anchor="middle" font-size="${data.length>6?10:12}" fill="var(--muted)">${esc(r.label.length>16?r.label.slice(0,15)+'…':r.label)}</text>`;
 });
 svg+='</svg>';el('tax06-graf').innerHTML=svg;
 el('tax06-tabell').innerHTML='<table><thead><tr>'+headers.map(k=>'<th>'+esc(k)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(v=>'<td>'+esc(String(v))+'</td>').join('')+'</tr>').join('')+'</tbody></table>';
 const csvQ=v=>'"'+String(v).replace(/"/g,'""')+'"';
 const csv='\uFEFF'+[headers,...rows].map(r=>r.map(csvQ).join(';')).join('\r\n')+'\r\n';
 el('tax06-csv').onclick=()=>lastNedTekst(csv,'norsk-okonomi-del06-'+mode+'.csv');
}
function beregnSkatt06(){
 const market=Number(el('tax06-verdi').value)*1e6, taxable=market*.8;
 const t1=Math.max(0,Math.min(taxable,21.5e6)-1.9e6)*.01;
 const t2=Math.max(0,taxable-21.5e6)*.011;
 const total=t1+t2,div=total/.6216,pre=div/.78;
 el('tax06-verdi-tekst').textContent=nfmt(market/1e6,0)+' mill. kr';
 el('tax06-beregning').innerHTML='<strong>Skattemessig aksjeformue etter formell 20 % rabatt:</strong> '+nfmt(taxable,0)+' kr<br><strong>Beregnet formuesskatt:</strong> '+nfmt(total,0)+' kr<br><strong>Illustrativt brutto utbytte ved full finansiering fra utbytte:</strong> '+nfmt(div,0)+' kr<br><strong>Illustrert nødvendig selskapoverskudd før 22 % selskapsskatt:</strong> '+nfmt(pre,0)+' kr';
}
el('tax06-valg').addEventListener('change',tegnSkatt06);
el('tax06-verdi').addEventListener('input',beregnSkatt06);
tegnSkatt06();beregnSkatt06();


// Delrapport 07: ulike regnskap, populasjoner og tjenestemål plottes aldri som én serie.
let avlest07=[],overskrift07='';
function datakilde07(mode){
 if(mode==='cofog')return {title:'COFOG-utgifter etter formål, 2025',unit:'mrd. kr',key:'K113',note:'Årsverdier i løpende kroner. COFOG viser formålet med utgiften; alminnelig offentlig tjenesteyting er ikke ensbetydende med administrasjon. Noe intern bruk av varer og tjenester inngår i disse formålene.',rows:COFOG_07.filter(r=>r.aar===2025).map(r=>({label:r.formaal,value:r.verdi_mill_kr/1000}))};
 if(mode==='total')return {title:'Samlede offentlige utgifter, 2021–2025',unit:'mrd. kr',key:'K113',note:'Nominell norsk total utgiftsserie fra SSBs reviderte 2026-vintage. Ingen inflasjonsjustering; endringer er ikke mål på administrativ vekst.',rows:OFF_07.filter(r=>r.indikator==='Totale utgifter').map(r=>({label:String(r.aar),value:r.verdi_mill_kr/1000}))};
 if(mode==='stilling')return {title:'Offentlig forvaltnings andel av jobbforhold',unit:'prosent',key:'K114',note:'Jobbforhold i 2. kvartal; samme person kan ha flere jobber. Andelen er ikke offentlig sysselsetting målt som personer eller årsverk.',rows:JOB_07.map(r=>({label:String(r.aar),value:r.offentlig_andel_jobber_prosent}))};
 if(mode==='innkjop')return {title:'Offentlige innkjøp, 2024–2025',unit:'mrd. kr',key:'K115',note:'Offentlige anskaffelser i definert SSB/DFØ-populasjon. Beløpene overlapper offentlige utgifter; skal ikke summeres og er ikke teoretisk sparepotensial.',rows:HOVED_07.filter(r=>r.indikator==='Offentlige innkjøp').map(r=>({label:String(r.periode),value:Number(r.verdi)}))};
 return {title:'Helseutgifter per innbygger, 2025',unit:'USD kjøpekraftskorrigert',key:'K121',note:'OECD Health at a Glance 2025. Omfatter samlede helseutgifter, også private, og er derfor forskjellig fra COFOG helseutgifter.',rows:HOVED_07.filter(r=>r.indikator==='Helseutgifter per innbygger PPP').map(r=>({label:r.gruppe,value:Number(r.verdi)}))};
}
function tegn07(){
 const mode=el('off07-valg').value, info=datakilde07(mode),data=info.rows;
 if(!data.length){el('off07-graf').textContent='Ingen registrerte data i valgt serie.';return;}
 overskrift07=info.title;avlest07=data;
 el('off07-tittel').textContent=info.title;
 el('off07-forklaring').textContent=info.note;
 el('off07-kilde').textContent='Kilde ['+info.key+']';el('off07-kilde').href='#'+info.key.toLowerCase();
 const W=815,left=260,right=100,step=data.length>6?37:50,top=29,H=top+data.length*step+36;
 const max=Math.max(1,...data.map(r=>r.value));const width=W-left-right;
 let svg=`<svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${esc(info.title)}; alle tall finnes i tabellen" viewBox="0 0 ${W} ${H}">`;
 for(let k=0;k<=4;k++){const v=max*k/4, x=left+width*k/4; svg+=`<line x1="${x}" x2="${x}" y1="${top-7}" y2="${H-24}" stroke="var(--line)"/><text x="${x}" y="${H-7}" font-size="11" text-anchor="middle" fill="var(--muted)">${esc(nfmt(v,v<10?1:0))}</text>`;}
 data.forEach((r,i)=>{const y=top+i*step,barw=Math.max(1,width*r.value/max), label=r.label.length>35?r.label.slice(0,34)+'…':r.label;
  svg+=`<text x="${left-12}" y="${y+15}" text-anchor="end" font-size="${data.length>6?12:14}" fill="var(--ink2)">${esc(label)}</text><rect x="${left}" y="${y}" width="${barw}" height="21" rx="3" fill="${i===0?'var(--main)':'#87aeb3'}"><title>${esc(r.label)}: ${esc(nfmt(r.value,r.value<10?1:0))} ${esc(info.unit)}</title></rect><text x="${left+barw+8}" y="${y+15}" font-size="12" font-weight="700" fill="var(--ink)">${esc(nfmt(r.value,r.value<10?2:1))}</text>`;
 });
 svg+='</svg>';el('off07-graf').innerHTML=svg;
 el('off07-tabell').innerHTML='<table><thead><tr><th>År / kategori</th><th>'+esc(info.unit)+'</th></tr></thead><tbody>'+data.map(r=>'<tr><td>'+esc(r.label)+'</td><td>'+esc(nfmt(r.value,2))+'</td></tr>').join('')+'</tbody></table>';
 const quote=v=>'"'+String(v).replace(/"/g,'""')+'"';
 el('off07-csv').onclick=()=>lastNedTekst('\uFEFF'+[['Kategori/år',info.unit,'Kilde-ID'],...data.map(r=>[r.label,String(r.value),info.key])].map(row=>row.map(quote).join(';')).join('\r\n')+'\r\n','norsk-okonomi-07-'+mode+'.csv');
}
function beregnBaumol07(){
 const g=Number(el('off07-produktiv').value),t=Number(el('off07-tjeneste').value),years=Number(el('off07-aar').value);
 for(const [id,v] of [['off07-produktiv-v',g],['off07-tjeneste-v',t]])el(id).textContent=nfmt(v,2)+' %';
 el('off07-aar-v').textContent=years+' år';
 const factor=Math.pow((1+g/100)/(1+t/100),years),pct=(factor-1)*100;
 el('off07-baumol-resultat').innerHTML='<b>'+esc((pct>0?'+':'')+nfmt(pct,1))+' %</b>Relativ tjenestekostnad etter '+years+' år i den stiliserte modellen. Faktor: '+esc(nfmt(factor,3))+' × referanseåret. Negativt resultat innebærer fallende relativ enhetskostnad, ikke nødvendigvis fallende nominell pris.';
}
function beregnInnkjop07(){
 const rate=Number(el('off07-innkjopandel').value),gross=864*rate/100;
 el('off07-innkjopandel-v').textContent=nfmt(rate,1)+' %';
 el('off07-innkjop-resultat').innerHTML='<b>'+esc(nfmt(gross,2))+' mrd. kr</b>Ren multiplikasjon: 864 mrd. × '+esc(nfmt(rate,1))+' %. Dette er ikke en dokumentert innsparing og kan ikke bokføres som effekt av reform.';
}
el('off07-valg').addEventListener('change',tegn07);
['off07-produktiv','off07-tjeneste','off07-aar'].forEach(id=>el(id).addEventListener('input',beregnBaumol07));
el('off07-innkjopandel').addEventListener('input',beregnInnkjop07);
tegn07();beregnBaumol07();beregnInnkjop07();

